170	/****************************************************************************
171	 * Name: gdwifi_start
172	 *
173	 * Description:
174	 *   Platform bring-up subset of the SDK platform_init() (skipping the
175	 *   pieces NuttX already owns: clocks, ECLIC, console, tick) followed by
176	 *   the Wi-Fi stack start.  Called once from the wifi application.
177	 ****************************************************************************/
178	
179	extern void sys_os_init(void);
180	extern void systick_init(void);
181	extern void rom_init(void);
182	extern void dma_config(void);
183	extern void sysctrl_init(void);
184	extern void rf_power_on(void);
185	extern int  wifi_power_on(void);
186	extern void wifi_power_off(void);
187	extern void raw_flash_init(void);
188	extern int  nvds_flash_internal_init(void);
189	extern int  wifi_init(void);
190	extern void sys_wakelock_acquire(uint32_t lock_id);
191	
192	#define GDWIFI_LOCK_ID_WLAN  0
193	
194	int gdwifi_start(void)
195	{
196	  static bool started;
197	
198	  if (started)
199	    {
200	      return 0;
201	    }
202	
203	#define GDWIFI_STEP(name, call) \
204	  do { syslog(LOG_INFO, "gdwifi: " name "\n"); call; } while (0)
205	
206	  GDWIFI_STEP("sys_os_init", sys_os_init());
207	  GDWIFI_STEP("systick_init", systick_init());
208	
209	  /* Peripheral clocks the SDK platform_init() would have enabled before
210	   * touching TRNG/CRC/PMU registers (unclocked AHB access bus-hangs).
211	   */
212	
213	  modifyreg32(GD32VW55X_RCU_APB1EN, 0, RCU_APB1EN_PMUEN);
214	  modifyreg32(GD32VW55X_RCU_AHB2EN, 0, RCU_AHB2EN_TRNGEN);
215	  modifyreg32(GD32VW55X_RCU_AHB1EN, 0, RCU_AHB1EN_CRCEN);
216	
217	  GDWIFI_STEP("rom_init", rom_init());
218	  GDWIFI_STEP("dma_config", dma_config());
219	  GDWIFI_STEP("sysctrl_init", sysctrl_init());
220	  GDWIFI_STEP("rf_power_on", rf_power_on());
221	
222	  /* Power the Wi-Fi PMU domain before any Wi-Fi interrupt can fire: a
223	   * spurious WIFI_INTGEN with the domain off spins forever inside
224	   * wifi_lpds_exit() in interrupt context.
225	   */
226	
227	  /* Cycle the Wi-Fi power domain: a JTAG/system reset does not clear the
228	   * radio PMU state left by a previous run, and the MAC init asserts on
229	   * dirty registers.
230	   */
231	
232	  GDWIFI_STEP("wifi_power_off", wifi_power_off());
233	  GDWIFI_STEP("wifi_power_on", wifi_power_on());
234	  GDWIFI_STEP("raw_flash_init", raw_flash_init());
235	
236	  if (nvds_flash_internal_init() != 0)
237	    {
238	      nerr("nvds flash init failed\n");
239	    }
240	
241	  GDWIFI_STEP("irq_attach", gdwifi_irq_attach());
242	
243	  /* Hold the WLAN wakelock for good: the LPDS/doze path of the vendor
244	   * firmware spins forever in wifi_lpds_exit() waiting for a PMU wake-up
245	   * this port does not implement yet (PM phase).  With the lock held the
246	   * MAC never enters low-power, so that path is never taken.
247	   */
248	
249	  sys_wakelock_acquire(GDWIFI_LOCK_ID_WLAN);
250	
251	  syslog(LOG_INFO, "gdwifi: wifi_init\n");
252	  if (wifi_init() != 0)
253	    {
254	      nerr("wifi_init failed\n");
255	      return -1;
256	    }
257	
258	  syslog(LOG_INFO, "gdwifi: wifi_init done\n");
259	
260	  started = true;
261	  return 0;
262	}
