246	/****************************************************************************
247	 * Name: gd32_ble_conn_evt_handler
248	 *
249	 * Description:
250	 *   A connection stops the legacy advertising set and the stack leaves it
251	 *   stopped, so after the first central connects (or aborts the attempt)
252	 *   the device would never be discoverable again until a reset.  Restart
253	 *   the set on every disconnection.
254	 *
255	 ****************************************************************************/
256	
257	static void gd32_ble_conn_evt_handler(ble_conn_evt_t event,
258	                                      ble_conn_data_u *p_data)
259	{
260	  if (event == BLE_CONN_EVT_STATE_CHG &&
261	      p_data->conn_state.state == BLE_CONN_STATE_DISCONNECTD &&
262	      g_adv_idx != 0xff)
263	    {
264	      wlinfo("BLE disconnected (reason 0x%x), restarting advertising\n",
265	             p_data->conn_state.info.discon_info.reason);
266	      ble_adv_restart(g_adv_idx);
267	    }
268	}
