266	void ble_pmu_config(uint32_t enable)
267	{
268	    if (enable) {
269	        /* if ble is sleep, config power on */
270	        if (pmu_flag_get(PMU_FLAG_BLE_SLEEP) == SET)
271	            pmu_ble_control(PMU_BLE_WAKE);
272	        /* wait active */
273	        while (pmu_flag_get(PMU_FLAG_BLE_ACTIVE) != SET);
274	    } else {
275	        /* if ble is active, config power off */
276	        if (pmu_flag_get(PMU_FLAG_BLE_ACTIVE) == SET)
277	            pmu_ble_control(PMU_BLE_SLEEP);
278	        /* wait sleep */
279	        while (pmu_flag_get(PMU_FLAG_BLE_SLEEP) != SET);
280	    }
281	}
