251	/****************************************************************************
252	 * Name: gd32_ble_conn_evt_handler
253	 *
254	 * Description:
255	 *   A connection stops the legacy advertising set and the stack leaves it
256	 *   stopped, so after the first central connects (or aborts the attempt)
257	 *   the device would never be discoverable again until a reset.  Restart
258	 *   the set on every disconnection.
259	 *
260	 ****************************************************************************/
261	
262	static void gd32_ble_conn_evt_handler(ble_conn_evt_t event,
263	                                      ble_conn_data_u *p_data)
264	{
265	  if (event == BLE_CONN_EVT_STATE_CHG &&
266	      p_data->conn_state.state == BLE_CONN_STATE_DISCONNECTD &&
267	      g_adv_idx != 0xff)
268	    {
269	      wlinfo("BLE disconnected (reason 0x%x), restarting advertising\n",
270	             p_data->conn_state.info.discon_info.reason);
271	      ble_adv_restart(g_adv_idx);
272	    }
273	}
