/****************************************************************************
 * Name: board_early_initialize
 *
 * Description:
 *   board_early_initialize() runs on the IDLE thread before the scheduler
 *   starts (lockcount == 1).  Placing gd32_bringup() here ensures WiFi
 *   and BLE tasks are created while the scheduler is still locked, so
 *   BLE callback registration completes before the BLE task can fire
 *   events — no sched_lock() wrapper needed.
 *
 ****************************************************************************/

#ifdef CONFIG_BOARD_EARLY_INITIALIZE
void board_early_initialize(void)
{
  gd32_bringup();
}
#endif

